"% model.m - Robust stability margins of cascaded inner + outer loop

% Inner loop plant
s = tf('s');
G_in = 1 / (s * (s + 4.0));

% Inner-loop feedback gain
ki = 12.0;

% Close the inner loop with unity negative feedback around ki*G_in
G_in_cl = feedback(ki * G_in, 1);

% Outer-loop plant/compensator
G_out = 2.5 / (s * (s + 2.0));

% Total open loop: outer cascade of the closed inner loop
L = G_out * G_in_cl;

% Compute gain and phase margins
[Gm, Pm, Wcg, Wcp] = margin(L);

% Convert gain margin to dB
gm_db  = 20 * log10(Gm);
pm_deg = Pm;

% Wcg = frequency at which phase crosses -180 deg  -> phase crossover w_pc
% Wcp = frequency at which magnitude crosses 0 dB  -> gain crossover  w_gc
w_pc = Wcg;
w_gc = Wcp;

% Build result struct
result.gm_db  = gm_db;
result.pm_deg = pm_deg;
result.w_gc   = w_gc;
result.w_pc   = w_pc;

% Write result.json in the current working directory
fid = fopen('result.json', 'w');
fwrite(fid, jsonencode(result));
fclose(fid);"
